package bo.com.ganadero.sanidad.api;
import bo.com.ganadero.sanidad.application.*;import bo.com.ganadero.sanidad.domain.*;import bo.com.ganadero.shared.api.ApiResponse;import bo.com.ganadero.shared.web.CorrelationIdFilter;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/sanidad") public class ClinicaController{private final ClinicaService service;public ClinicaController(ClinicaService s){service=s;}@PostMapping("/casos-clinicos")ApiResponse<CasoClinico>crearCaso(@Valid@RequestBody CrearCasoClinicoRequest b,HttpServletRequest r){return ok(service.crearCaso(b.command()),r);}@GetMapping("/casos-clinicos")ApiResponse<List<CasoClinico>>casos(@RequestParam(required=false)UUID animalId,HttpServletRequest r){return ok(service.casos(animalId),r);}@PostMapping("/casos-clinicos/{id}/cerrar")ApiResponse<CasoClinico>cerrar(@PathVariable UUID id,@Valid@RequestBody CerrarCasoClinicoRequest b,HttpServletRequest r){return ok(service.cerrarCaso(id,b.resultado()),r);}@PostMapping("/tratamientos")ApiResponse<Tratamiento>crear(@Valid@RequestBody CrearTratamientoRequest b,HttpServletRequest r){return ok(service.crearTratamiento(b.command()),r);}@GetMapping("/tratamientos")ApiResponse<List<Tratamiento>>tratamientos(@RequestParam(required=false)UUID animalId,HttpServletRequest r){return ok(service.tratamientos(animalId),r);}@PostMapping("/tratamientos/{id}/activar")ApiResponse<List<AplicacionTratamiento>>activar(@PathVariable UUID id,HttpServletRequest r){return ok(service.activar(id),r);}@PostMapping("/tratamientos/{id}/regenerar")ApiResponse<List<AplicacionTratamiento>>regenerar(@PathVariable UUID id,HttpServletRequest r){return ok(service.regenerar(id),r);}@GetMapping("/tratamientos/{id}/aplicaciones")ApiResponse<List<AplicacionTratamiento>>aplicaciones(@PathVariable UUID id,HttpServletRequest r){return ok(service.aplicaciones(id),r);}@PostMapping("/tratamientos/{tratamientoId}/aplicaciones/{aplicacionId}/aplicar")ApiResponse<AplicacionTratamiento>aplicar(@PathVariable UUID tratamientoId,@PathVariable UUID aplicacionId,@Valid@RequestBody AplicarTratamientoRequest b,HttpServletRequest r){return ok(service.aplicar(tratamientoId,aplicacionId,b.command()),r);}@PostMapping("/tratamientos/aplicaciones/marcar-atrasadas")ApiResponse<List<AplicacionTratamiento>>atrasadas(HttpServletRequest r){return ok(service.marcarAtrasadas(),r);}@PostMapping("/tratamientos/{id}/finalizar")ApiResponse<Tratamiento>finalizar(@PathVariable UUID id,HttpServletRequest r){return ok(service.finalizar(id),r);}private<T>ApiResponse<T>ok(T d,HttpServletRequest r){Object c=r.getAttribute(CorrelationIdFilter.ATTRIBUTE);return ApiResponse.success(d,c==null?"unknown":c.toString());}}
